#!/usr/bin/env bash
# Makes a timestamped tar.gz of a directory and keeps only the newest N.
# Usage: ./backup.sh <source_dir> <backup_dir> [keep]
set -euo pipefail

usage() {
  echo "Usage: $0 <source_dir> <backup_dir> [keep]" >&2
  exit 1
}

[[ $# -ge 2 ]] || usage
SRC="${1%/}"
DEST="$2"
KEEP="${3:-5}"

[[ -d "$SRC" ]] || { echo "Source not found: $SRC" >&2; exit 2; }
mkdir -p "$DEST"

base="$(basename "$SRC")"
stamp="$(date +%Y%m%d-%H%M%S)"
archive="$DEST/${base}-${stamp}.tar.gz"

tar -czf "$archive" -C "$(dirname "$SRC")" "$base"
echo "Created: $archive"

# File names are generated by this script, so parsing ls is safe here.
# shellcheck disable=SC2012
ls -1t "$DEST"/"${base}"-*.tar.gz | tail -n +"$((KEEP + 1))" | while read -r old; do
  echo "Removing old backup: $old"
  rm -- "$old"
done